<?php
require_once __DIR__ . '/includes.php';
$keys=['store_name'=>'Store name','store_tagline'=>'Tagline','store_description'=>'Store description','announcement'=>'Announcement bar','hero_eyebrow'=>'Hero eyebrow','hero_heading'=>'Hero heading','hero_description'=>'Hero description','hero_cta'=>'Hero button text','hero_image'=>'Hero image URL/path','promo_heading'=>'Promotion heading','promo_description'=>'Promotion description','promo_image'=>'Promotion image URL/path','promo_url'=>'Promotion link','brand_story_heading'=>'Brand story heading','brand_story'=>'Brand story','contact_email'=>'Contact email','contact_whatsapp'=>'WhatsApp number','contact_address'=>'Contact address','instagram_url'=>'Instagram URL','tiktok_url'=>'TikTok URL','shipping_fee'=>'Shipping fee'];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();foreach($keys as $key=>$label){$value=trim((string)($_POST[$key]??''));if($key==='shipping_fee'&&(!is_numeric($value)||(float)$value<0))continue;$stmt=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$stmt->execute([$key,$value]);}flash('success','Store settings updated.');redirect('settings.php');}
admin_header('Store settings');
?><section class="admin-panel"><form method="post" class="admin-settings-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php foreach($keys as $key=>$label): $value=setting($key); ?><label><?=e($label)?><?php if(in_array($key,['store_description','hero_description','brand_story','contact_address','promo_description'],true)): ?><textarea name="<?=e($key)?>" rows="3"><?=e($value)?></textarea><?php else: ?><input name="<?=e($key)?>" value="<?=e($value)?>" maxlength="1000" <?=$key==='contact_email'?'type="email"':''?>><?php endif; ?></label><?php endforeach; ?><button class="button button-dark" type="submit">SAVE SETTINGS</button></form></section><?php admin_footer(); ?>
